export function verse(n: number): string {
  const animals = [
    {
      name: "fly",
      swallowed: "I don't know why she swallowed the fly. Perhaps she'll die.",
    },
    {
      name: "spider",
      swallowed: "It wriggled and jiggled and tickled inside her.",
      catch: "fly",
    },
    {
      name: "bird",
      swallowed: "How absurd to swallow a bird!",
      catch: "spider",
    },
    {
      name: "cat",
      swallowed: "Imagine that, to swallow a cat!",
      catch: "bird",
    },
    {
      name: "dog",
      swallowed: "What a hog, to swallow a dog!",
      catch: "cat",
    },
    {
      name: "goat",
      swallowed: "Just opened her throat and swallowed a goat!",
      catch: "dog",
    },
    {
      name: "cow",
      swallowed: "I don't know how she swallowed a cow!",
      catch: "goat",
    },
    {
      name: "horse",
      swallowed: "She's dead, of course!",
    },
  ];

  if (n < 1 || n > animals.length) {
    throw new Error("Invalid verse number");
  }

  let result = `I know an old lady who swallowed a ${animals[n - 1].name}.\n`;

  if (n === 8) {
    result += animals[n - 1].swallowed + "\n";
  } else {
    result += animals[n - 1].swallowed + "\n";
    for (let i = n - 1; i > 0; i--) {
      result += `She swallowed the ${animals[i].name} to catch the ${animals[i - 1].name}${
        i === 1 ? " that wriggled and jiggled and tickled inside her" : ""
      }.\n`;
    }
  }

  return result;
}

export function verses(start: number, end: number): string {
  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i) + "\n";
  }
  return result.trim() + "\n";
}
